import math

def control(obs):
    target_gaze = -23.0
    speed = -0.7
    hitch = obs.get('hitch_deg', 0.0)

    views = obs.get('views', {})
    cam = views.get('camera')
    direct = views.get('direct')

    target_hitch = -6.0

    if cam and 'walls' in cam and cam['walls']:
        left_dists = []
        right_dists = []
        for b, d in cam['walls']:
            rel_b = (b - (-hitch + 180.0) + 180.0) % 360.0 - 180.0
            lat = d * math.sin(math.radians(rel_b))
            long_d = -d * math.cos(math.radians(rel_b))
            if long_d > 0.1:
                if lat > 0.1:
                    left_dists.append(lat)
                elif lat < -0.1:
                    right_dists.append(-lat)
        if left_dists and right_dists:
            diff = min(left_dists) - min(right_dists)
            target_hitch = max(-16.0, min(8.0, diff * 10.0 - 3.0))
        elif left_dists:
            target_hitch = -10.0

    hitch_err = hitch - target_hitch
    steer = hitch_err * 1.5

    # Protect front corners: check direct view rails
    if direct and 'walls' in direct:
        for b, d in direct['walls']:
            if -60.0 < b < -20.0 and d < 2.2:
                # Front right barrier close, reduce right steering
                steer = max(steer, -4.0)
            elif 20.0 < b < 60.0 and d < 2.2:
                steer = min(steer, 4.0)

    steer = max(-16.0, min(16.0, steer))

    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': target_gaze}

