import math

state = {
    'phase': 'PULL_FWD',
    'fwd_target_dist': 2.8,
    'start_covered': None,
}

def control(obs):
    global state
    status = obs.get('status', '')
    hitch_deg = obs.get('hitch_deg', 0.0)
    steer_deg = obs.get('steer_deg', 0.0)
    progress = obs.get('progress', {})
    covered = progress.get('covered', 0.0)
    target_info = obs.get('target', {})

    if state['phase'] == 'PULL_FWD':
        if state['start_covered'] is None:
            state['start_covered'] = covered

        dist_pulled = state['start_covered'] - covered
        if dist_pulled < 1.2:
            target_steer = 15.0
        elif dist_pulled < 2.0:
            target_steer = -10.0
        else:
            target_steer = 0.0

        speed_mps = 0.5

        if dist_pulled >= state['fwd_target_dist']:
            state['phase'] = 'REVERSE'
            state['start_covered'] = None

        return (target_steer, speed_mps, 0.0)

    look_deg = -150.0 if (int(obs.get('t', 0.0) * 2) % 4 < 2) else 150.0
    speed_mps = -0.25

    if target_info.get('in_sight'):
        tb = target_info.get('bearing_deg', 0.0)
        rel = tb - 180.0
        while rel > 180.0: rel -= 360.0
        while rel < -180.0: rel += 360.0
        target_hitch = max(-10.0, min(10.0, -rel * 0.35))
    else:
        target_hitch = 0.0

    hitch_err = hitch_deg - target_hitch
    target_steer = hitch_err * 2.0
    target_steer = max(-22.0, min(22.0, target_steer))

    return (target_steer, speed_mps, look_deg)

